import React, { useEffect, useState } from "react";
import Navbar from "../components/Navbar";
import { api, API_BASE } from "../utils/api";
import { motion } from "framer-motion";

export default function Portal() {
  const [loading, setLoading] = useState(true);
  const [cases, setCases] = useState([]);

  // New report form states
  const [submitting, setSubmitting] = useState(false);
  const [category, setCategory] = useState("WHATSAPP");
  const [message, setMessage] = useState("");
  const [suspectNumber, setSuspectNumber] = useState("");
  const [link, setLink] = useState("");
  const [screenshot, setScreenshot] = useState(null);

  function getTokenOrRedirect() {
    const token = localStorage.getItem("user_token");
    if (!token) {
      window.location.href = "/login";
      return null;
    }
    return token;
  }

  async function loadMyCases() {
    const token = getTokenOrRedirect();
    if (!token) return;

    const res = await api.get("/api/portal/my-cases", {
      headers: { Authorization: `Bearer ${token}` }
    });

    setCases(res.data || []);
  }

  useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        await loadMyCases();
      } finally {
        setLoading(false);
      }
    })();
    // eslint-disable-next-line
  }, []);

  function logout() {
    localStorage.removeItem("user_token");
    localStorage.removeItem("user_profile");
    window.location.href = "/";
  }

  async function submitCase(e) {
    e.preventDefault();

    const token = getTokenOrRedirect();
    if (!token) return;

    if (!message.trim()) {
      alert("Please enter your message");
      return;
    }

    setSubmitting(true);
    try {
      const form = new FormData();
      form.append("category", category);
      form.append("message", message);
      form.append("suspectNumber", suspectNumber);
      form.append("link", link);

      if (screenshot) {
        form.append("screenshot", screenshot);
      }

      await api.post("/api/portal/report", form, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "multipart/form-data"
        }
      });

      // reset form
      setCategory("WHATSAPP");
      setMessage("");
      setSuspectNumber("");
      setLink("");
      setScreenshot(null);

      alert("Report submitted ✅");

      // reload cases
      await loadMyCases();
    } catch (err) {
      console.log(err);
      alert("Failed to submit report ❌");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-50 via-white to-gray-50">
      <Navbar />

      <div className="max-w-5xl mx-auto px-4 py-10">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 14 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.55, ease: "easeOut" }}
          className="flex justify-between items-center gap-4 flex-wrap"
        >
          <div>
            <h1 className="text-4xl font-black tracking-tight">My Portal</h1>
            <p className="text-gray-600 mt-1 text-lg">
              Track your scam reports and SOC reply.
            </p>
          </div>

          <button
            onClick={logout}
            className="px-6 py-3 rounded-2xl bg-gray-900 text-white font-semibold hover:opacity-95 active:scale-[0.99] transition"
          >
            Logout
          </button>
        </motion.div>

        {/* REPORT FORM */}
        <motion.div
          initial={{ opacity: 0, y: 14 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.55, delay: 0.05 }}
          className="mt-10 bg-white rounded-3xl shadow p-7 border"
        >
          <div className="text-2xl font-black">Report a Scam</div>
          <p className="text-gray-600 mt-1 text-sm">
            Submit details and screenshot (optional). SOC will reply here.
          </p>

          <form onSubmit={submitCase} className="mt-6 space-y-5">
            <div>
              <div className="text-sm font-semibold mb-2">Category</div>
              <select
                className="w-full border rounded-2xl px-4 py-3 bg-white focus:outline-none focus:ring-2 focus:ring-gray-900/10"
                value={category}
                onChange={(e) => setCategory(e.target.value)}
              >
                <option value="WHATSAPP">WHATSAPP</option>
                <option value="CALL">CALL</option>
                <option value="SMS">SMS</option>
                <option value="UPI">UPI</option>
                <option value="BANK">BANK</option>
                <option value="EMAIL">EMAIL</option>
                <option value="WEBSITE">WEBSITE</option>
                <option value="OTHER">OTHER</option>
              </select>
            </div>

            <div>
              <div className="text-sm font-semibold mb-2">Your Message *</div>
              <textarea
                className="w-full border rounded-2xl px-4 py-3 min-h-[130px] focus:outline-none focus:ring-2 focus:ring-gray-900/10"
                placeholder="Explain what happened..."
                value={message}
                onChange={(e) => setMessage(e.target.value)}
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <div className="text-sm font-semibold mb-2">
                  Suspect Number (optional)
                </div>
                <input
                  className="w-full border rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-gray-900/10"
                  placeholder="e.g. 9876543210"
                  value={suspectNumber}
                  onChange={(e) => setSuspectNumber(e.target.value)}
                />
              </div>

              <div>
                <div className="text-sm font-semibold mb-2">
                  Link (optional)
                </div>
                <input
                  className="w-full border rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-gray-900/10"
                  placeholder="Paste scam link if any"
                  value={link}
                  onChange={(e) => setLink(e.target.value)}
                />
              </div>
            </div>

            <div>
              <div className="text-sm font-semibold mb-2">
                Screenshot (optional)
              </div>

              <input
                type="file"
                accept="image/png,image/jpeg,image/webp"
                onChange={(e) => setScreenshot(e.target.files?.[0] || null)}
              />

              {screenshot && (
                <div className="text-xs text-gray-600 mt-2">
                  Selected: <b>{screenshot.name}</b>
                </div>
              )}
            </div>

            <button
              disabled={submitting}
              className="px-6 py-3 rounded-2xl bg-gray-900 text-white font-semibold w-full hover:opacity-95 active:scale-[0.99] transition disabled:opacity-60"
            >
              {submitting ? "Submitting..." : "Submit Report"}
            </button>

            <div className="text-xs text-gray-600 leading-relaxed">
              🔒 CyberRaksha never asks for OTP/password and we do not take
              remote access.
            </div>
          </form>
        </motion.div>

        {/* MY CASES */}
        <motion.div
          initial={{ opacity: 0, y: 14 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.55, delay: 0.1 }}
          className="mt-12"
        >
          <div className="text-2xl font-black">My Reports</div>
          <p className="text-gray-600 mt-1 text-sm">
            Your submitted reports will appear here.
          </p>

          {loading ? (
            <div className="mt-6 text-gray-600">Loading...</div>
          ) : (
            <div className="mt-6 space-y-5">
              {cases.map((c, idx) => (
                <motion.div
                  key={c._id}
                  initial={{ opacity: 0, y: 16 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.45, delay: idx * 0.06 }}
                  className="bg-white rounded-3xl shadow p-7 border"
                >
                  <div className="flex justify-between items-center gap-4 flex-wrap">
                    <div className="font-black text-xl">{c.ticketId}</div>

                    <div className="text-xs font-bold px-3 py-2 rounded-full border bg-gray-50">
                      {c.status} • {c.severity}
                    </div>
                  </div>

                  <div className="text-sm text-gray-600 mt-2">
                    {new Date(c.createdAt).toLocaleString()}
                  </div>

                  <div className="mt-5 text-sm">
                    <b>Your Message:</b>
                    <div className="mt-2 whitespace-pre-wrap text-gray-800 leading-relaxed">
                      {c.message}
                    </div>
                  </div>

                  {c.suspectNumber && (
                    <div className="text-sm mt-4">
                      <b>Suspect Number:</b> {c.suspectNumber}
                    </div>
                  )}

                  {c.link && (
                    <div className="text-sm mt-2">
                      <b>Link:</b>{" "}
                      <a
                        href={c.link}
                        target="_blank"
                        rel="noreferrer"
                        className="text-blue-600 underline break-all"
                      >
                        {c.link}
                      </a>
                    </div>
                  )}

                  {c.analystReply && (
                    <div className="mt-6 border rounded-3xl p-5 bg-gray-50">
                      <div className="font-black text-lg">SOC Reply</div>
                      <div className="mt-2 whitespace-pre-wrap text-gray-800 leading-relaxed">
                        {c.analystReply}
                      </div>
                    </div>
                  )}

                  {c.screenshotUrl ? (
                    <div className="mt-6">
                      <div className="font-semibold text-sm">Screenshot</div>

                      <img
                        alt="screenshot"
                        className="mt-2 rounded-2xl border w-full max-w-[560px] object-contain bg-white"
                        src={`${API_BASE}${c.screenshotUrl}`}
                        onError={(e) => {
                          e.target.style.display = "none";
                        }}
                      />

                      <a
                        href={`${API_BASE}${c.screenshotUrl}`}
                        target="_blank"
                        rel="noreferrer"
                        className="text-blue-600 underline text-sm mt-2 inline-block"
                      >
                        Open Screenshot
                      </a>
                    </div>
                  ) : (
                    <div className="mt-5 text-sm text-gray-500">
                      No screenshot uploaded.
                    </div>
                  )}
                </motion.div>
              ))}

              {cases.length === 0 && (
                <div className="text-gray-600 mt-4">No cases yet.</div>
              )}
            </div>
          )}
        </motion.div>
      </div>
    </div>
  );
}
